package vn.iotstar.service.impl;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import vn.iotstar.dto.RegisterDTO;import vn.iotstar.entity.*;import vn.iotstar.repository.*;import vn.iotstar.service.*;@Service public class AuthServiceImpl implements AuthService{public AuthServiceImpl(UserRepository ur,RoleRepository rr,PasswordEncoder enc,OtpService otp){this.ur=ur;this.rr=rr;this.enc=enc;this.otp=otp;}final UserRepository ur;final RoleRepository rr;final PasswordEncoder enc;final OtpService otp;@Transactional public void register(RegisterDTO d){if(ur.existsByUsername(d.getUsername()))throw new IllegalArgumentException("Username đã tồn tại");if(ur.existsByEmail(d.getEmail()))throw new IllegalArgumentException("Email đã tồn tại");if(!d.getPassword().equals(d.getConfirmPassword()))throw new IllegalArgumentException("Mật khẩu xác nhận không đúng");Role r=rr.findByName("ROLE_USER").orElseThrow(()->new IllegalStateException("Chưa có ROLE_USER"));ur.save(new User(null,d.getUsername(),d.getEmail(),enc.encode(d.getPassword()),d.getFullName(),false,r,new java.util.ArrayList<>()));otp.sendRegisterOtp(d.getEmail());}@Transactional public boolean verifyRegister(String e,String o){if(!otp.verifyRegisterOtp(e,o))return false;User u=ur.findByEmail(e).orElseThrow(()->new IllegalArgumentException("User không tồn tại"));u.setEnabled(true);return true;}@Transactional public void forgotPassword(String e){if(!ur.existsByEmail(e))throw new IllegalArgumentException("Email không tồn tại");otp.sendResetPasswordOtp(e);}public boolean verifyResetOtp(String e,String o){return otp.verifyResetPasswordOtp(e,o);}@Transactional public void resetPassword(String e,String p){User u=ur.findByEmail(e).orElseThrow(()->new IllegalArgumentException("Email không tồn tại"));u.setPassword(enc.encode(p));}}
